3	// Chunks are concatenated as bytes, not strings: a multi-byte character can be
4	// split across two chunks, and decoding each chunk on its own would corrupt it.
5	const readStdin = async (): Promise<string> => {
6	  const chunks: Buffer[] = [];
7	  for await (const chunk of process.stdin) chunks.push(chunk as Buffer);
8	  return Buffer.concat(chunks).toString("utf8");
9	};
10	
11	// The MHPCO trusts its own schema: input is taken to be a scenario as described
12	// there, which is what this cast asserts.
13	const parseScenario = (input: string): Scenario => JSON.parse(input) as Scenario;
14	
15	const EXIT_REJECTED = 1;
16	
17	try {
18	  const results = runScenario(parseScenario(await readStdin()));
19	  process.stdout.write(JSON.stringify(results));
20	} catch (error) {
21	  process.stderr.write(`${error instanceof Error ? error.message : error}\n`);
22	  process.exit(EXIT_REJECTED);
23	}
